mapper.select:
select bf.id, bf.api_code, bf.file_type, bf.file_name, bf.status, bf.complete, bf.actual_number, bf.create_time, bf.error_actual_number, bf.push_start_time, bf.push_end_time, bf.push_number, bc.short_name, bc.cid from b_local_file bf inner join b_marketing_customer bc on bc.api_code = bf.api_code where bf.file_type in ('qiqi','xiecheng','yiqianbao','dianxiao','halo','haier','zhongan','xiechengsms','marketingData','dx_transform','didi', 'xiechengsmscollidingvt','zhongbang_caifu','zhongbanglabel','haierColliding','tongcheng_operation_pushToCustomer', 'tongcheng_undo_pushToCustomer','dewucollidingdata','zhongbang_voice','wuba_colliding','xiecheng_cps_colliding')
and ( bc.cid like concat("%", #{search},"%") or bc.short_name like concat("%", #{search},"%"))
and bc.api_code =#{apiCode}
and bf.create_time >=#{uploadStartTime}
and bf.create_time <#{uploadEndTime}
and bf.file_type in (${fileType})
order by bf.create_time desc

select sum(bf.actual_number),bf.api_code from b_local_file bf left join b_marketing_customer bc on bc.api_code = bf.api_code where bf.file_type in ('qiqi','xiecheng','yiqianbao','dianxiao','halo','haier','zhongan','xiechengsms','marketingData','dx_transform','didi', 'xiechengsmscollidingvt','zhongbang_caifu','zhongbanglabel','haierColliding','tongcheng_operation_pushToCustomer', 'tongcheng_undo_pushToCustomer','dewucollidingdata','zhongbang_voice','wuba_colliding','xiecheng_cps_colliding')
and ( bc.cid like concat("%", #{search},"%") or bc.short_name like concat("%", #{search},"%"))
and bc.api_code =#{apiCode}
and bf.create_time >=#{uploadStartTime}
and bf.create_time <#{uploadEndTime}
and bf.file_type in (${fileType})

